#!/usr/bin/env python3
"""Collect every item's review status and notes into docs/REVIEW-NOTES.md,
grouped by category, so teachers and experts can review the drafts.

    python3 tools/review-notes.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
from lafa import kb  # noqa: E402

def main():
    base = kb.KnowledgeBase(); lines = ["# Review notes for every encyclopedia item", "",
            "Generated by `tools/review-notes.py` from the `review` field of each item. Status `draft` means",
            "the item was written from the listed sources and still needs an expert check.", ""]
    by_cat = {}
    for item in base.all(): by_cat.setdefault(item.category, []).append(item)
    for cat in kb.CATEGORIES:
        items = by_cat.get(cat.key, [])
        if not items: continue
        lines += [f"## {kb.text(cat.title, 'en')} ({len(items)})", ""]
        for item in sorted(items, key=lambda i: base.plan_rank(i.id)):
            review = item.get("review") if isinstance(item.get("review"), dict) else {}
            notes = " ".join(str(review.get("notes", "")).split()) or "—"
            lines.append(f"- **{item.title('en')}** (`{item.id}`, {review.get('status', 'draft')}, {len(item.sources())} sources): {notes}")
        lines.append("")
    out = ROOT / "docs" / "REVIEW-NOTES.md"; out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"{out.relative_to(ROOT)}: {len(base.all())} items")

if __name__ == "__main__":
    main()
